-- 427: WASSCE English essay-writing multiple-choice set A and structured question (batch sprint 1).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_427_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_427_guard;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_ess_mcq_001' AND NOT (q.topic_id IS 'topic_wassce_english_essay' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An essay that tells a story is called' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. a narrative essay","B. an expository essay","C. an argumentative essay","D. a descriptive essay"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Narrative essays recount events; expository essays explain, argumentative essays persuade and descriptive essays paint pictures with words.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_ess_mcq_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_ess_mcq_002' AND NOT (q.topic_id IS 'topic_wassce_english_essay' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The introduction of an essay is expected to' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. list all the writer''s sources of information","B. present the topic and indicate the direction the essay will take","C. state the conclusion of the essay in full","D. describe the writer''s school in detail"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A good introduction presents the topic and shows the line the essay will follow; sources, full conclusions and personal detail do not belong there.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_ess_mcq_002' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_ess_mcq_003' AND NOT (q.topic_id IS 'topic_wassce_english_essay' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A well-developed paragraph normally discusses' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. as many ideas as possible","B. only direct quotations","C. one main idea","D. the opposite of its topic sentence"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Unity is the rule of paragraphing: one main idea, stated in a topic sentence, is developed by the other sentences.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_ess_mcq_003' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_ess_mcq_004' AND NOT (q.topic_id IS 'topic_wassce_english_essay' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following topics calls for a descriptive essay?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Should corporal punishment be abolished in schools?","B. Write a story that ends with the words: it was all a dream.","C. Explain how to prepare for an examination.","D. My hometown on the morning of the annual festival"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The festival scene asks the writer to paint a picture of a place and moment — descriptive writing. The others are argumentative, narrative and expository.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Classify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_ess_mcq_004' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_ess_st_001' AND NOT (q.topic_id IS 'topic_wassce_english_essay' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'You are to write an article for the school magazine on the topic: "Keeping Our School Compound Clean". Answer these planning questions.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) An expository article for the school magazine, addressed to students and staff. (b) A catchy title, a byline with the writer''s name, and organised paragraphs from introduction to conclusion. (c) Students can keep the compound clean by using the litter bins and joining the weekly clean-up exercise.' AND q.explanation IS 'Match the task: (a) an expository article for the school community; (b) title, byline and organised paragraphs; (c) one clear sentence on how students can help.' AND q.difficulty IS 'medium' AND q.points IS '10' AND q.marks IS '10' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Plan' AND q.assessment_objective IS NULL AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_ess_st_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_ess_st_001_a' AND NOT (sp.id IS 'sqp_q_eng_s1_ess_st_001_a' AND sp.question_id IS 'q_eng_s1_ess_st_001' AND sp.part_label IS 'a' AND sp.part_text IS 'State the type of composition required and its intended audience.' AND sp.marks IS '3' AND sp.correct_answer IS 'An expository article for the school magazine, addressed to students and staff.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_ess_st_001_b' AND NOT (sp.id IS 'sqp_q_eng_s1_ess_st_001_b' AND sp.question_id IS 'q_eng_s1_ess_st_001' AND sp.part_label IS 'b' AND sp.part_text IS 'State three features of the format of a magazine article.' AND sp.marks IS '4' AND sp.correct_answer IS 'A catchy title, a byline with the writer''s name, and organised paragraphs from introduction to conclusion.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_427_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_ess_st_001_c' AND NOT (sp.id IS 'sqp_q_eng_s1_ess_st_001_c' AND sp.question_id IS 'q_eng_s1_ess_st_001' AND sp.part_label IS 'c' AND sp.part_text IS 'Write one suitable topic sentence for a paragraph on how students can help.' AND sp.marks IS '3' AND sp.correct_answer IS 'Students can keep the compound clean by using the litter bins and joining the weekly clean-up exercise.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '2')) THEN 1 ELSE 0 END;
